import test from'node:test';import{execFileSync}from'node:child_process';import{readFileSync}from'node:fs';import assert from'node:assert/strict';import{validateCandidate,existingGrantState,enroll}from'./enroll_internal_smtp_operator.mjs';
const expected={username:'phone-tester',organization:'aihr-test',origin:'https://onehr-staging.chinhingroup.com',humanApprovalReference:'explicit human staging-only grant'};
const c={username:'phone-tester',organization:'aihr-test',enabled:true,emailVerified:true,mustChange:false,password:'sealed-hash',totpSecret:'private-fixture',subject:'subject',tenantId:'tenant',issuer:expected.origin+'/auth/tenant',version:'version',email:'verified@example.invalid'};
const b={subject:c.subject,issuer:c.issuer,tenant_id:c.tenantId,revoked_at:null,blocked:false,group_admin:true,app_user_id:'app-user'};
test('exact existing verified MFA-ready staging administrator is selected',()=>assert.equal(validateCandidate(c,b,expected).username,'phone-tester'));
test('different login namespace origin identity readiness or prior HR authority refuses',()=>{for(const key of['username','organization','enabled','emailVerified','mustChange','password','totpSecret','issuer']){const value={...c,[key]:['enabled','emailVerified'].includes(key)?false:key==='mustChange'?true:key==='password'||key==='totpSecret'?null:'other'};assert.throws(()=>validateCandidate(value,b,expected),key);}for(const value of[{...b,revoked_at:'yesterday'},{...b,blocked:true},{...b,group_admin:false},{...b,subject:'different'},{...b,tenant_id:'different'}])assert.throws(()=>validateCandidate(c,value,expected));assert.throws(()=>validateCandidate(c,b,{...expected,origin:'https://production.example.invalid'}));});
test('reviewed immutable binding and verified mailbox cannot be replaced',()=>{const fixed={...expected,...validateCandidate(c,b,expected)};for(const [key,value]of[['subject','other'],['version','other'],['email','other@example.invalid']])assert.throws(()=>validateCandidate({...c,[key]:value},b,fixed));});
test('no grant or exact idempotent grant only; revoked or different test address refuses',()=>{assert.equal(existingGrantState([],c),'absent');assert.equal(existingGrantState([{revoked_at:null,test_email:c.email}],c),'already-enrolled');assert.throws(()=>existingGrantState([{revoked_at:'yesterday',test_email:c.email}],c));assert.throws(()=>existingGrantState([{revoked_at:null,test_email:'other@example.invalid'}],c));});
function fixture({deny=false,changed=false,existing=false}={}){const calls=[];let inserted=false,audited=false;let snapshots=0;const tx={unsafe:async(sql,args)=>{calls.push(sql);if(sql.includes('pg_advisory'))return[];if(sql.includes('bool_and'))return[{allowed:true}];if(sql.startsWith('select i.issuer'))return[b];if(sql.startsWith('select test_email'))return existing?[{test_email:c.email,revoked_at:null}]:[];if(sql.startsWith('select record_key')){snapshots++;return[{record_key:'credential',sealed:changed&&snapshots>1?'different':'same',expires_at:null,updated_at:'same'}];}if(sql.startsWith('select * from role_assignment'))return[{id:'unchanged-role'}];if(sql.startsWith('select * from app_external_identity'))return[{id:'unchanged-binding'}];if(sql.startsWith('select * from deployment_identity_operator'))return[{id:'legacy-operator'}];if(sql.startsWith('insert into deployment_identity_operator')){inserted=true;return[{issuer:c.issuer}];}if(sql.includes('append_auth_event')){audited=true;return[];}if(sql.includes('set_config'))return[];if(sql.includes('internal_auth_email_operator'))return[{allowed:!deny}];throw Error('Unrecognized SQL');}};const db={begin:async(mode,fn)=>{const before={inserted,audited};try{return await fn(tx);}catch(e){inserted=before.inserted;audited=before.audited;throw e;}}};return{db,readRecord:async(_tx,key)=>key.startsWith('login:')?{subject:c.subject}:c,calls,get state(){return{inserted,audited};}};}
test('preview performs no mutation and exposes only reviewed candidate metadata',async()=>{const f=fixture();const x=await enroll({db:f.db,readRecord:f.readRecord,expected,apply:false});assert.equal(x.readOnly,true);assert.equal(x.changes.password,false);assert(!f.calls.some(x=>/insert into|append_auth_event|set_config/.test(x)));assert(!JSON.stringify(x).includes('private-fixture'));});
test('apply inserts only operator binding and canonical audit, preserves credential and HR rows',async()=>{const f=fixture();const x=await enroll({db:f.db,readRecord:f.readRecord,expected,apply:true});assert(x.canonicalEmailAuthorizationVerified&&x.created);assert.deepEqual(f.state,{inserted:true,audited:true});assert.equal(f.calls.filter(x=>x.startsWith('insert into')).length,1);assert(!f.calls.some(x=>/^update |^delete /i.test(x)));});
test('authorization or credential-custody failure rolls back grant and audit together',async()=>{for(const options of[{deny:true},{changed:true}]){const f=fixture(options);await assert.rejects(enroll({db:f.db,readRecord:f.readRecord,expected,apply:true}));assert.deepEqual(f.state,{inserted:false,audited:false});}});
test('existing identical enrollment is idempotent with no duplicate event',async()=>{const f=fixture({existing:true});const x=await enroll({db:f.db,readRecord:f.readRecord,expected,apply:true});assert.equal(x.created,false);assert.deepEqual(f.state,{inserted:false,audited:false});});

test('root bootstrap syntax and privilege drop keep application code outside OS root',()=>{const wrapper=new URL('./enroll_smtp_operator.py',import.meta.url);const code="import ast,sys; source=open(sys.argv[1]).read(); tree=ast.parse(source); value=next(n.value.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='BOOTSTRAP' for t in n.targets)); ast.parse(value); assert 'user=1000,group=1000,extra_groups=[]' in value; assert 'os.O_CREAT|os.O_EXCL' in value; assert 'hashlib.sha256(copied)' in value; assert 'child=subprocess.run' in value";execFileSync('python3',['-I','-c',code,wrapper.pathname]);});
